import type { OutcomeCardsPayload } from '../types/evotwin';

/**
 * Load the day-365 outcome cards.
 *
 * The artifact is generated by `danon.outcome_export.export_outcome_cards` and
 * copied into `public/evotwin/`, so it is served from the app's own base path
 * with no backend needed. A missing artifact is reported as such rather than
 * replaced with placeholder numbers: a dashboard that invents a day-365
 * outcome is worse than one that says it has no data.
 */
export async function loadOutcomeCards(): Promise<OutcomeCardsPayload> {
  const url = `${import.meta.env.BASE_URL}evotwin/outcome_cards.json`;
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) {
    throw new Error(
      `outcome cards not found at ${url} (${res.status}). Generate them with:\n` +
        `python -c "from danon.outcome_export import export_outcome_cards" … ` +
        `or copy outputs_real/outcome_cards.json into frontend/public/evotwin/.`,
    );
  }
  const payload = (await res.json()) as OutcomeCardsPayload;
  if (!payload.cases?.length) {
    throw new Error('outcome cards artifact contains no cases');
  }
  return payload;
}
